pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(address(c), 1 ether);

        Receiver recv = new Receiver();

        bool ok;
        vm.prank(caller);
        try c.sendTo(address(recv), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}

contract Receiver {
    receive() external payable {}
}
